import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0xb9cbd1);
scene.fog=new THREE.FogExp2(0xc5d2d5,0.0048);
const camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.08,420);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const hemi=new THREE.HemisphereLight(0xe4f2f7,0x69756f,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffedcf,2.4);sun.position.set(-45,85,-35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-115;sun.shadow.camera.right=115;sun.shadow.camera.top=115;sun.shadow.camera.bottom=-115;sun.shadow.bias=-.0002;scene.add(sun);
const clock=new THREE.Clock(),raycaster=new THREE.Raycaster();
const mats={snow:new THREE.MeshStandardMaterial({color:0xe6edf0,roughness:.92}),snowShade:new THREE.MeshStandardMaterial({color:0xc9d6d9,roughness:.95}),stone:new THREE.MeshStandardMaterial({color:0x777d78,roughness:1}),stoneDark:new THREE.MeshStandardMaterial({color:0x424a48,roughness:1}),wood:new THREE.MeshStandardMaterial({color:0x604e3b,roughness:1}),woodDark:new THREE.MeshStandardMaterial({color:0x382f27,roughness:1}),roof:new THREE.MeshStandardMaterial({color:0x434847,roughness:1}),bark:new THREE.MeshStandardMaterial({color:0x514b42}),pine:new THREE.MeshStandardMaterial({color:0x32473f,roughness:1}),pine2:new THREE.MeshStandardMaterial({color:0x52635a,roughness:1}),metal:new THREE.MeshStandardMaterial({color:0x303a3d,metalness:.5,roughness:.6}),tire:new THREE.MeshStandardMaterial({color:0x171b1b,roughness:1}),glass:new THREE.MeshStandardMaterial({color:0x293d44,metalness:.4,roughness:.3}),uniform:new THREE.MeshStandardMaterial({color:0x435349,roughness:1}),enemy:new THREE.MeshStandardMaterial({color:0x68513a,roughness:.95}),enemy2:new THREE.MeshStandardMaterial({color:0x514633,roughness:1}),skin:new THREE.MeshStandardMaterial({color:0xb78d70,roughness:1}),helmet:new THREE.MeshStandardMaterial({color:0x5d4931,roughness:.9}),flagA:new THREE.MeshStandardMaterial({color:0x009b48,side:THREE.DoubleSide}),flagW:new THREE.MeshStandardMaterial({color:0xf5f2e7,side:THREE.DoubleSide}),flagR:new THREE.MeshStandardMaterial({color:0xed2939,side:THREE.DoubleSide}),flagEnemyR:new THREE.MeshStandardMaterial({color:0xd54d55,side:THREE.DoubleSide}),flagBlue:new THREE.MeshStandardMaterial({color:0x174c8c,side:THREE.DoubleSide}),flagOrange:new THREE.MeshStandardMaterial({color:0xe38b38,side:THREE.DoubleSide})};
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,12,10),cylGeo=new THREE.CylinderGeometry(1,1,1,10),coneGeo=new THREE.ConeGeometry(1,1,7),capsuleGeo=new THREE.CapsuleGeometry(.17,.48,4,8);
function box(parent,mat,x,y,z,sx,sy,sz){const m=new THREE.Mesh(boxGeo,mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,mat,x,y,z,sx,sy,sz){const m=new THREE.Mesh(sphereGeo,mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;parent.add(m);return m}
function cylinder(parent,mat,x,y,z,r1,r2,h,segments=10){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function groundHeight(x,z){return .22*Math.sin(x*.043)*Math.cos(z*.051)+.12*Math.sin(z*.09+x*.035)}
const worldSize=220;const terrainGeo=new THREE.PlaneGeometry(worldSize,worldSize,150,150);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i);pos.setY(i,groundHeight(x,z))}terrainGeo.computeVertexNormals();const ground=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({color:0xdde7e8,roughness:1}));ground.receiveShadow=true;scene.add(ground);
// distant snowy ridge silhouettes
for(let i=0;i<13;i++){const x=-105+i*17,z=-100-Math.random()*12,h=14+Math.random()*18;const hill=new THREE.Mesh(new THREE.ConeGeometry(12+Math.random()*10,h,5),mats.snowShade);hill.position.set(x,h*.34,z);hill.rotation.y=Math.random()*2;hill.receiveShadow=true;scene.add(hill)}
// soft patches of windblown snow
for(let i=0;i<400;i++){const x=(Math.random()-.5)*205,z=(Math.random()-.5)*205;const r=1+Math.random()*5;const patch=new THREE.Mesh(new THREE.CircleGeometry(r,8),new THREE.MeshBasicMaterial({color:Math.random()>.5?0xffffff:0xdce7e9,transparent:true,opacity:.08,depthWrite:false}));patch.rotation.x=-Math.PI/2;patch.position.set(x,groundHeight(x,z)+.035,z);scene.add(patch)}
const villages=[{x:-65,z:-48,name:'ÇAYLI KƏNDİ'},{x:-12,z:-66,name:'DAŞLI YÜKSƏKLİK'},{x:48,z:-48,name:'QARLI DƏRƏ'},{x:63,z:15,name:'KÖHNƏ MƏHƏLLƏ'},{x:15,z:59,name:'MEŞƏ KƏNARI'},{x:-53,z:47,name:'CƏNUB MÖVQEYİ'}];
const capturePoints=[],enemies=[],obstacles=[],decor=[];
function house(x,z,rot=0,variant=0){const g=new THREE.Group();g.position.set(x,groundHeight(x,z),z);g.rotation.y=rot;scene.add(g);const w=7+variant*.8,d=6+variant*.6,h=3.1;
// rubble foundation and broken wall sections leave broad doorways
box(g,mats.stone,0,.38,-d/2,w,.78,.42);box(g,mats.stone,-w/2,.4,0,.42,.8,d);box(g,mats.stone,w/2,.4,-1.15,.42,.8,d-2.3);box(g,mats.stone,w/2,.4,d/2,w,.8,.42);
box(g,mats.stone,-w/2,1.9,-d/2,.42,2.2,.42);box(g,mats.stone,0,2.1,-d/2,w*.57,1.8,.42);box(g,mats.stone,w/2,1.3,-d/2,.42,1.1,.42);
box(g,mats.stone,-w/2,1.9,0,.42,2.2,d);box(g,mats.stone,w/2,1.65,1.75,.42,1.7,d-3.5);box(g,mats.stone,0,1.8,d/2,w,2,.42);
// exposed roof beams, partially collapsed roof
box(g,mats.wood,0,3.35,-d/2,w+.5,.2,.26);box(g,mats.wood,-w/2,3.35,0,.22,.2,d);box(g,mats.wood,w/2,3.35,-1.7,.22,.2,d-3.4);box(g,mats.wood,0,3.35,d/2,w,.2,.22);
box(g,mats.roof,-1,3.55,-.9,w*.58,.18,d*.58).rotation.z=-.12;
// smashed windows and debris
for(let i=0;i<8;i++){const rx=(Math.random()-.5)*w*1.25,rz=(Math.random()-.5)*d*1.25;const rock=box(g,Math.random()>.5?mats.stone:mats.stoneDark,rx,.15+Math.random()*.2,rz,.3+Math.random()*.7,.22,.25+Math.random()*.6);rock.rotation.y=Math.random()*3}
const flagpole=cylinder(g,mats.metal,-w*.31,2.7,-d*.5-.16,.045,.045,5,8);const flagGroup=new THREE.Group();flagGroup.position.set(-w*.3,4.7,-d*.5-.2);g.add(flagGroup);const flag=new THREE.Group();flagGroup.add(flag);const occupiedMats=[mats.flagEnemyR,mats.flagBlue,mats.flagOrange];for(let j=0;j<3;j++)box(flag,occupiedMats[j],.62,.65-j*.43,0,1.25,.44,.035);box(flag,mats.flagR,.62,.65,0,1.25,.44,.04);
// tiny broken chimney
if(variant%2===0)box(g,mats.stoneDark,w*.3,3.6,d*.2,.75,1.4,.8);
return {group:g,flag,flagpole,x,z,w,d,rot,variant}}
function makePine(x,z,s=1){const g=new THREE.Group();g.position.set(x,groundHeight(x,z),z);scene.add(g);cylinder(g,mats.bark,0,.8*s,0,.17*s,.23*s,1.7*s,7);for(let i=0;i<3;i++){const c=new THREE.Mesh(coneGeo,i===1?mats.pine2:mats.pine);c.position.set(0,(1.5+i*.67)*s,0);c.scale.set((1.1-i*.17)*s,(1.7-i*.2)*s,(1.1-i*.17)*s);c.castShadow=true;g.add(c)}decor.push(g)}
function makeCar(x,z,type='sandcat',rot=0){const g=new THREE.Group();g.position.set(x,groundHeight(x,z),z);g.rotation.y=rot;scene.add(g);const isTruck=type==='katyusha',length=isTruck?6.6:4.7,width=isTruck?2.45:2.2;
box(g,isTruck?mats.uniform:mats.enemy2,0,.95,0,length,1.1,width);box(g,mats.glass,-.6,1.8,0,1.5,.75,width*.87);box(g,mats.metal,isTruck?1.4:1.55,1.45,0,isTruck?2.6:1.1,.45,width*.98);
if(isTruck){for(let i=0;i<12;i++){const tube=cylinder(g,mats.metal,1.35,2.05,-.92+i*.168,.12,.12,2.55,8);tube.rotation.z=Math.PI/2;tube.rotation.x=Math.PI/2}box(g,mats.metal,-1.6,1.75,0,2.3,.32,2.1)}
else{for(let i=-1;i<=1;i++)box(g,mats.glass,-.55,1.82,i*.6,.72,.54,.52)}
for(const xx of [-1.6,1.55])for(const zz of [-width*.59,width*.59]){const tire=cylinder(g,mats.tire,xx,.48,zz,.48,.48,.25,12);tire.rotation.x=Math.PI/2;const hub=cylinder(g,mats.metal,xx,.48,zz*1.02,.18,.18,.28,10);hub.rotation.x=Math.PI/2}
box(g,mats.metal,0,.22,width*.53,length*.88,.18,.18);return g}
for(let v=0;v<villages.length;v++){const site=villages[v];for(let i=0;i<4;i++){const a=i*Math.PI/2+.24*(v%2),r=6+Math.random()*4;house(site.x+Math.cos(a)*r,site.z+Math.sin(a)*r,a+Math.PI/2,(i+v)%3)}
const point={x:site.x,z:site.z,name:site.name,captured:false,progress:0,group:new THREE.Group()};point.group.position.set(site.x,groundHeight(site.x,site.z)+.035,site.z);scene.add(point.group);const ring=new THREE.Mesh(new THREE.RingGeometry(8.7,9,48),new THREE.MeshBasicMaterial({color:0xd6ba78,transparent:true,opacity:.35,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;point.group.add(ring);const ring2=new THREE.Mesh(new THREE.RingGeometry(8.45,8.55,48),new THREE.MeshBasicMaterial({color:0xe0d5ae,transparent:true,opacity:.25,side:THREE.DoubleSide}));ring2.rotation.x=-Math.PI/2;point.group.add(ring2);capturePoints.push(point);
for(let n=0;n<3;n++)makeEnemy(site.x+(Math.random()-.5)*11,site.z+(Math.random()-.5)*10,v,n);
}
for(let i=0;i<78;i++){const x=(Math.random()-.5)*195,z=(Math.random()-.5)*195;if(villages.some(v=>Math.hypot(v.x-x,v.z-z)<13))continue;makePine(x,z,.65+Math.random()*.8)}
makeCar(-25,-20,'sandcat',-.7);makeCar(24,7,'katyusha',1.8);makeCar(-85,25,'sandcat',.35);

