makeCar(-25,-20,'sandcat',-.7);makeCar(24,7,'katyusha',1.8);makeCar(-85,25,'sandcat',.35);

function makeEnemy(x,z,siteIndex,slot){const g=new THREE.Group();g.position.set(x,groundHeight(x,z),z);scene.add(g);const isOfficer=slot===0;const torso=box(g,isOfficer?mats.enemy:mats.enemy2,0,1.05,0,.62,.78,.34);torso.rotation.z=-.03;sphere(g,mats.skin,0,1.68,0,.22,.25,.22);const helmet=sphere(g,mats.helmet,0,1.84,0,.25,.15,.25);helmet.scale.y=.7;box(g,mats.enemy2,0,1.65,0,.48,.06,.37);
for(const side of [-1,1]){const leg=new THREE.Mesh(capsuleGeo,isOfficer?mats.enemy:mats.enemy2);leg.position.set(side*.18,.45,0);leg.rotation.z=side*-.05;leg.castShadow=true;g.add(leg);const arm=new THREE.Mesh(capsuleGeo,isOfficer?mats.enemy:mats.enemy2);arm.scale.set(.72,.93,.8);arm.position.set(side*.4,1.1,-.05);arm.rotation.z=side*-.55;arm.rotation.x=-.3;arm.castShadow=true;g.add(arm)}
const gun=box(g,mats.metal,.02,1.16,-.48,.13,.13,.72);gun.rotation.x=.16;const enemy={group:g,x,z,siteIndex,alive:true,hp:3,cool:1+Math.random()*1.8,move:Math.random()*6,hitFlash:0,bodyMats:[torso.material],gun};enemies.push(enemy);return enemy}
// first-person weapon arms and detailed receiver, visible at the lower right
const weaponRoot=new THREE.Group();camera.add(weaponRoot);scene.add(camera);weaponRoot.position.set(.35,-.32,-.68);
const sleeveMat=new THREE.MeshStandardMaterial({color:0x34433d,roughness:.9}),gloveMat=new THREE.MeshStandardMaterial({color:0x4a473b,roughness:.9}),weaponMat=new THREE.MeshStandardMaterial({color:0x242b2b,metalness:.6,roughness:.4}),woodMat=new THREE.MeshStandardMaterial({color:0x594638,roughness:.8});
box(weaponRoot,sleeveMat,-.16,-.16,.04,.22,.2,.3).rotation.z=-.25;sphere(weaponRoot,gloveMat,-.13,-.09,-.08,.12,.1,.16);
const receiver=box(weaponRoot,weaponMat,.04,-.015,-.16,.18,.17,.48);box(weaponRoot,woodMat,.06,-.12,-.16,.16,.08,.28);box(weaponRoot,weaponMat,.04,.1,-.48,.055,.055,.52);box(weaponRoot,weaponMat,.04,.15,-.66,.08,.07,.07);box(weaponRoot,weaponMat,.04,-.14,.08,.12,.25,.12);box(weaponRoot,woodMat,.04,-.17,-.18,.13,.08,.27);
const muzzleFlash=new THREE.PointLight(0xffbd66,0,4);muzzleFlash.position.set(.04,.08,-.78);weaponRoot.add(muzzleFlash);
const player={pos:new THREE.Vector3(0,0,87),vel:new THREE.Vector3(),yaw:0,pitch:0,health:100,ammo:30,reserve:120,weapon:0,shooting:false,crouched:false,grounded:true,reloading:false,dead:false,stepTimer:0,walkPhase:0,recoil:0};
camera.position.set(player.pos.x,groundHeight(player.pos.x,player.pos.z)+1.68,player.pos.z);const keys={},mobileMove={forward:false,back:false,left:false,right:false};let started=false,paused=false,muted=false,fireHeld=false,lastShot=0,toastTimer=0,damageTimer=0,shotCount=0;let audioCtx=null,masterGain=null;
const weapons=[{name:'AK-74',type:'AVTOMATİK · 5.45×39',capacity:30,rate:105,damage:1,spread:.009},{name:'AK-47',type:'AVTOMATİK · 7.62×39',capacity:30,rate:145,damage:1,spread:.013}];
function audio(){if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();masterGain=audioCtx.createGain();masterGain.gain.value=muted?0:.28;masterGain.connect(audioCtx.destination)}if(audioCtx.state==='suspended')audioCtx.resume()}
function noise(duration,frequency,volume,filterType='lowpass'){if(!audioCtx||muted)return;const buffer=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*duration),audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const source=audioCtx.createBufferSource();source.buffer=buffer;const filter=audioCtx.createBiquadFilter();filter.type=filterType;filter.frequency.value=frequency;const gain=audioCtx.createGain();gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);source.connect(filter);filter.connect(gain);gain.connect(masterGain);source.start()}
function tone(freq,duration,volume,type='sine'){if(!audioCtx||muted)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,freq*.42),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(masterGain);o.start();o.stop(audioCtx.currentTime+duration)}
function playShot(){audio();tone(player.weapon===0?104:85,.16,.32,'sawtooth');noise(.22,1300,.3);tone(48,.17,.2,'triangle');noise(.06,3200,.08,'highpass')}
function playStep(run=false){noise(.13,run?600:430,run?.12:.08);tone(run?70:55,.09,.07,'triangle')}
function playReload(){noise(.12,900,.12,'highpass');setTimeout(()=>noise(.18,600,.15,'highpass'),300);setTimeout(()=>tone(150,.12,.12,'triangle'),630)}
function say(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2200)}

